CREATE OR REPLACE FUNCTION get_plant_age(p_sitekey text)
RETURNS numeric AS $$
DECLARE
    v_goliveon date;
BEGIN
    SELECT goliveon INTO v_goliveon
    FROM plants
    WHERE sitekey = p_sitekey;

    RETURN EXTRACT(YEAR FROM AGE(CURRENT_DATE, v_goliveon));
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_plant_age(p_sitekey text)
RETURNS integer AS $$
DECLARE
    v_goliveon date;
BEGIN
    SELECT goliveon INTO v_goliveon
    FROM plants
    WHERE sitekey = p_sitekey;

    RETURN (CURRENT_DATE - v_goliveon) / 365;
END;
$$ LANGUAGE plpgsql;

